<script setup>
import { onMounted, ref, computed } from 'vue';
import KfeFormShell from './KfeFormShell.vue';
const props=defineProps({application:{type:Object,required:true}});
const emit=defineEmits(['save-request','back']);
const editing=ref(false),detail=ref(''),records=ref([]),loading=ref(false),error=ref('');
const initial={type:'',cost:'',start:'',end:''};
const today=computed(()=>new Date().toISOString().slice(0,10));
async function load(){loading.value=true;error.value='';try{const model=await props.application.getAdminState();records.value=model?.history?.compliance||[]}catch(e){error.value=String(e?.message||e);records.value=[]}finally{loading.value=false}}
function save(value){emit('save-request',{module:'Compliance',value});}
function openDetail(value){detail.value=value;if(value==='history'||value==='validity')void load();}
function closeDetail(){detail.value='';}
const valid=row=>String(row.validity_start||'')<=today.value&&String(row.validity_end||'')>=today.value;
onMounted(load);
</script>
<template><section class="kfe-module-view" aria-labelledby="compliance-title"><button class="kfe-secondary-action" type="button" @click="detail?closeDetail():editing?editing=false:emit('back')">‹ {{detail?'Compliance':editing?'Compliance':'More'}}</button><template v-if="detail"><p class="kfe-eyebrow">Vehicle Operations</p><h1 id="compliance-title">{{detail==='history'?'Renewal history':'Current validity'}}</h1><p v-if="loading" class="kfe-boundary-note" role="status">Loading authoritative compliance records…</p><p v-if="error" class="kfe-error-note" role="alert">{{error}}</p><template v-if="detail==='history'"><article v-for="row in records.slice().sort((a,b)=>String(b.validity_end||'').localeCompare(String(a.validity_end||'')))" :key="row.id" class="kfe-detail-card"><strong>{{row.renewal_type||'Renewal'}}</strong><p>₹{{(Number(row.cost_paise||0)/100).toFixed(2)}} · {{row.validity_start}} → {{row.validity_end}}</p></article><p v-if="!loading&&!records.length" class="kfe-boundary-note">No compliance records yet.</p></template><template v-else><article v-for="row in records.filter(valid)" :key="row.id" class="kfe-detail-card"><strong>{{row.renewal_type||'Renewal'}} · VALID</strong><p>{{row.validity_start}} → {{row.validity_end}}</p></article><p v-if="!loading&&!records.filter(valid).length" class="kfe-boundary-note">No active validity record.</p></template></template><template v-else-if="!editing"><p class="kfe-eyebrow">Vehicle Operations</p><h1 id="compliance-title">Compliance</h1><p class="kfe-destination-subtitle">Renewals, validity and historical records.</p><article class="kfe-action-card"><div><span class="kfe-card-label">Renewal</span><strong>Record a completed renewal</strong><p>Keep renewal type, cost and validity dates clear.</p></div><button class="kfe-primary-action" type="button" @click="editing=true">Add renewal</button></article><section class="kfe-module-section"><h2>Current validity</h2><button class="kfe-list-action" type="button" @click="openDetail('validity')"><span>Current validity</span><span aria-hidden="true">›</span></button></section><section class="kfe-module-section"><h2>History</h2><button class="kfe-list-action" type="button" @click="openDetail('history')"><span>Renewal history</span><span aria-hidden="true">›</span></button></section></template><KfeFormShell v-else draft-key="compliance-renewal" title="Add renewal" subtitle="Record a completed renewal." :initial-value="initial" @save="save"><template #default="{value}"><div class="kfe-form-field"><label class="kfe-form-label" for="renewal-type">Renewal type</label><input id="renewal-type" v-model="value.type" class="kfe-form-input" type="text" required /></div><div class="kfe-form-field"><label class="kfe-form-label" for="renewal-cost">Cost</label><input id="renewal-cost" v-model="value.cost" class="kfe-form-input" type="number" min="0" step="0.01" required /></div><div class="kfe-form-grid"><div class="kfe-form-field"><label class="kfe-form-label" for="renewal-start">Validity start</label><input id="renewal-start" v-model="value.start" class="kfe-form-input" type="date" required /></div><div class="kfe-form-field"><label class="kfe-form-label" for="renewal-end">Validity end</label><input id="renewal-end" v-model="value.end" class="kfe-form-input" type="date" required /></div></div><p class="kfe-form-boundary-note">Save submits the completed renewal to the application boundary.</p></template></KfeFormShell></section></template>